export default {"id":"note-level-13","number":13,"title":"Mastery","skillBand":"Textbook","duration":"From the course textbook","summary":"13.1","modules":[{"id":"note-m-13-1-101","code":"13.1","title":"13.1","blurb":"13.1","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l13-1-1","title":"13.1.1 — Map A: Idea → Capture → Scene → Export","blocks":[{"type":"step","title":"13.1.1 — Map A: Idea → Capture → Scene → Export","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.1 — End-to-end workflow maps (diagram literacy)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Draw Map A from idea to audio bounce using only Note, no Live and no Cloud."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Map A is the offline send. Beatmaking starts the idea (title, prompt, limitation, intention). Notes enter with <strong>Capture</strong> (Fixed: plus icon 1/2/4/8/16 then <strong>Add</strong>; Free: play then <strong>Capture</strong> / <strong>Create Clip</strong>). Clips live in Session. <strong>Scenes</strong> (max 8) are sections. <strong>Export Audio</strong> (Set Settings) renders scenes top to bottom to WAV 48 kHz 16-bit or M4A 48 kHz 32-bit."},{"type":"prose","html":"This map never opens Live. It is how you leave a phone-only sketch as a file. Greyed Export means no clips. Longest clip per scene sets that scene’s length."},{"type":"prose","html":"Draw boxes, not essays: Idea → Set Settings (tempo/key) → Capture → Editor (optional) → Scenes → Export Audio → Share to Files."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On paper, draw six boxes for Map A.","Under Capture, write Fixed vs Free in your own words.","Under Scenes, write “tap scene number / max 8.”","Under Export, write formats and top-to-bottom rule.","Walk a real Set through the boxes once (or point at an old lab).","Photograph the map for 13.1.6."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where does Map A end? <strong>Answer:</strong> An audio file via Export Audio / Share — not Live.","What if Export is greyed? <strong>Answer:</strong> The Set has no clips.","Does Map A require Cloud? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Beatmaking with Ableton Note (idea)","Ableton Note Manual §8.1 Capture; §4.3 Scenes; §10.2 Export","Note FAQ: Capture; export; 8 scenes","Capture in Note KB"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. One photographed Map A."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-1-1</code></em>"}]}],"minutes":8},{"id":"note-l13-1-2","title":"13.1.2 — Map B: Idea → Capture → Cloud → Live → Collect All and Save","blocks":[{"type":"step","title":"13.1.2 — Map B: Idea → Capture → Cloud → Live → Collect All and Save","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.1 — End-to-end workflow maps (diagram literacy)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Draw the professional transfer map, including the one-way door into Live."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Map B starts like Map A (idea, Capture, scenes) then forks to <strong>Ableton Cloud</strong> instead of (or after) a bounce. Enable Cloud, same email as the Live license, upload (Settings / banner / Set Options). Live <strong>11.2.5+</strong>, <strong>Show Cloud</strong>, open the Set, <strong>Collect All and Save</strong>. All Live editions can open Note Sets."},{"type":"prose","html":"Dead ends to draw as X marks: Live → Note (impossible); Cloud as backup (it is not); collaborator on another account (they need Share To…). Eight Cloud slots. 100 MB warning."},{"type":"prose","html":"Optional sibling arrow: Share To… .ablbundle if Cloud is full or the peer has no login."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Draw Idea → Capture → (scenes) → Upload Cloud → Live browser → Collect All and Save.","Draw a blocked arrow Live → Note.","Annotate: 8 slots, same email, Live ≥ 11.2.5.","Annotate Collect All and Save as mandatory before evicting Cloud.","Compare with Map A: B keeps devices; A is a bounce.","Photograph the map."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What Live version is required? <strong>Answer:</strong> 11.2.5 or later.","Why is Collect All and Save on the map? <strong>Answer:</strong> Samples can vanish if the Note Set leaves Cloud first.","Can the Live Project return to Note? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.1","Note FAQ: Cloud entire section","Note Compatibility","Using Note Presets in Live","Troubleshooting Problems with Note Files"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Photographed Map B with the blocked return arrow."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-1-2</code></em>"}]}],"minutes":8},{"id":"note-l13-1-3","title":"13.1.3 — Map C: Field sample → Slice → Resequence → Resample","blocks":[{"type":"step","title":"13.1.3 — Map C: Field sample → Slice → Resequence → Resample","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.1 — End-to-end workflow maps (diagram literacy)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Draw the sample-craft map with version gates on Slice and warp."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Map C is environmental audio as a beat."},{"type":"list","items":["<strong>Field sample</strong> — record into Drum Rack or Melodic Sampler, or import WAV/AIFF/M4A/MP3. Orange mic expected. Wired headphones preferred.","<strong>Slice</strong> — RN <strong>1.7.2</strong> Slice to Drum pads, or manual start points on multiple pads. Below 1.7.2, only manual.","<strong>Resequence</strong> — Capture a new pad order; MIDI Editor polish. Transpose on this path changes <strong>speed</strong> (FAQ). Note <strong>2.0.1 audio tracks</strong> warp; that is a parallel branch, not the sampler rule.","<strong>Resample</strong> — long-press mic → Resample Output to print the new groove onto one pad/Sampler (Manual §9.1)."],"ordered":true},{"type":"prose","html":"End the map at a clip you can put in a scene, then optionally join Map A or B."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Draw the four boxes plus a version flag on Slice (1.7.2+).","Draw a side note: sampler transpose = speed; 2.x audio ≠ that rule.","Draw Resample as long-press mic, not as Export Audio.","Walk one 12.4 Set through the boxes.","Photograph the map.","Write your installed version on the photo margin."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Is Slice available in all Note versions? <strong>Answer:</strong> No. 1.7.2+.","What does resample record? <strong>Answer:</strong> Note’s output, via long-press on the mic icon.","Does Map C replace Capture of MIDI drums? <strong>Answer:</strong> No. It is a sample path; you still Capture the pad performance."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Working with Samples in Note; Manual §9","RN 1.7.2 Slice; 2.0.1 audio warp","Note FAQ: warp/transpose; import formats","Capture in Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Photographed Map C with version flags."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-1-3</code></em>"}]}],"minutes":8},{"id":"note-l13-1-4","title":"13.1.4 — Map D: MIDI controller → Macros → Capture automation","blocks":[{"type":"step","title":"13.1.4 — Map D: MIDI controller → Macros → Capture automation","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.1 — End-to-end workflow maps (diagram literacy)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Draw hardware into Note: class-compliant MIDI → eight macros + actions → stored automation."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Map D is the controller lab in one line."},{"type":"list","items":["<strong>Connect:</strong> USB (adapter / powered hub if needed) or Bluetooth MIDI. Enable the device toggle. Remembered next time.","<strong>Play:</strong> selected track is armed. Pitch, length, velocity, aftertouch (poly AT 1.2.1). Not MPE, pitch bend, sustain.","<strong>Map:</strong> Settings → MIDI Settings → Mapping. Eight macros. Actions: Capture, Clear Capture, Start/Stop, Quantize, Undo, Redo (RN 1.0.15).","<strong>Automate:</strong> transport running, move mapped knobs, dotted line, <strong>Add</strong>, solid line + dots."],"ordered":false},{"type":"prose","html":"Magic Keyboard (iPad 1.2.1) is a cousin branch, not a MIDI map. Link is not on this map."},{"type":"prose","html":"No controller: draw the map anyway and mark “hardware missing.”"}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Draw Connect → Enable → Map 8 macros → Map Capture/Start-Stop → Play → Add automation.","List unsupported MIDI (MPE, PB, sustain) as a rejected box.","Annotate “transport must run” on the automation box.","If you have the 12.5 chart, clip it to this map.","Photograph."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many macros? <strong>Answer:</strong> Eight.","When is automation captured? <strong>Answer:</strong> Transport running + Add (or the UI commit you already use).","Is a Bluetooth speaker part of this map? <strong>Answer:</strong> No. Bluetooth MIDI ≠ Bluetooth headphones."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note MIDI Input; Manual §2.3–2.3.5","RN 1.0.15 mapping; 1.2.1 poly AT / Magic Keyboard","Manual §7.5 Automation","Note FAQ: MIDI controllers; no pitch bend"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Photographed Map D."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-1-4</code></em>"}]}],"minutes":8},{"id":"note-l13-1-5","title":"13.1.5 — Map E: Link jam → Link Audio → Live","blocks":[{"type":"step","title":"13.1.5 — Map E: Link jam → Link Audio → Live","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.1 — End-to-end workflow maps (diagram literacy)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Draw tempo-sync and optional audio stream as a jam map, separate from Cloud."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Map E is not Map B."},{"type":"list","items":["<strong>Link:</strong> App Settings → Link &amp; MIDI → Link → Ableton Link. Same Wi-Fi/LAN. Connected Peers. Optional Sync Start/Stop. Optional notifications.","<strong>Jam:</strong> each peer plays its own sound. Note still has 8 tracks / 8 scenes.","<strong>Link Audio (2.0+ / Live 12.4+):</strong> stream Note audio to Live and Push, send only. Optional.","<strong>After the jam:</strong> if you want the <strong>Set</strong> in Live, leave Map E and join <strong>Map B</strong> (Cloud or .ablbundle + Collect All and Save). Link Audio is not a Set transfer."],"ordered":false},{"type":"prose","html":"Skip branches if you lack a peer or version."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Draw Link enable → peers → tempo lock → optional Start/Stop.","Draw optional Link Audio to Live/Push with version flags.","Draw a dotted arrow “want the Set? → Map B.”","Draw failure: different Wi-Fi; Link Audio missing below 2.0.","Photograph."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Does Link upload Sets? <strong>Answer:</strong> No.","Which versions add Link Audio? <strong>Answer:</strong> Note 2.0 / 2.0.1 and Live 12.4 (send only).","First check for no peers? <strong>Answer:</strong> Same local network."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Using Link in Note","Manual §2.2.1","RN 2.0.1 Link Audio","Note Compatibility; Note FAQ Link Audio","Lesson 12.6"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Photographed Map E with the Map B hand-off dotted."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-1-5</code></em>"}]}],"minutes":8},{"id":"note-l13-1-6","title":"13.1.6 — Draw all five maps from memory","blocks":[{"type":"step","title":"13.1.6 — Draw all five maps from memory","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.1 — End-to-end workflow maps (diagram literacy)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Redraw Maps A–E with no notes open, then correct them against 13.1.1–13.1.5."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"This is diagram literacy, not a concert. From memory you must separate:"},{"type":"list","items":["<strong>A</strong> bounce","<strong>B</strong> Cloud → Live → collect","<strong>C</strong> sample → slice → resequence → resample","<strong>D</strong> controller → macros → automation","<strong>E</strong> Link → optional Link Audio → (Set still needs B)"],"ordered":false},{"type":"prose","html":"Common mixes to avoid: putting Collect All and Save on A; putting .mid export on any map; putting Live→Note on B; putting Slice on all versions; putting Link Audio on pre-2.0."},{"type":"prose","html":"Practice: five hand-drawn maps photographed into notes."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Close the previous lessons. Draw A–E on one spread.","Open 13.1.1–13.1.5. Mark errors in a second color.","Rewrite any map that mixed Cloud with Link or warp with sampler transpose.","Add your Note version once at the top of the page.","Photograph the corrected set.","Keep the page with the error library (13.2)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which map includes Collect All and Save? <strong>Answer:</strong> B only.","Which map is version-gated on Slice? <strong>Answer:</strong> C (1.7.2+).","Which map streams audio but does not transfer the Set? <strong>Answer:</strong> E (Link Audio)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Lessons 13.1.1–13.1.5 and their sources","Syllabus 13.1 practice"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Fifteen minutes. Five corrected photos."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-1-6</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-13-2-102","code":"13.2","title":"13.2","blurb":"13.2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l13-2-1","title":"13.2.1 — Capture buffer cleared unexpectedly → Timeout preference","blocks":[{"type":"step","title":"13.2.1 — Capture buffer cleared unexpectedly → Timeout preference","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"When uncommitted notes vanish after a pause, check Capture Timeout before you assume a crash."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"<strong>Capture Timeout</strong> (Preferences → Capture) is <strong>on by default</strong>. Uncaptured notes clear after you stop playing for a short period. <strong>Off:</strong> notes stay until you play again without having captured. Timeout <strong>does not</strong> affect overdub into existing clips (Manual §2.4.2)."},{"type":"prose","html":"RN <strong>1.0.12</strong> adds the setting. When <strong>VoiceOver</strong> is enabled, Capture buffer timeout is removed (RN 1.0.12) — a second reason the buffer may behave differently."},{"type":"prose","html":"The <strong>X</strong> next to Capture/Add also clears uncommitted notes on purpose. That is not Timeout."},{"type":"prose","html":"If the clip was already stored (solid notes, not outlines), Timeout is the wrong suspect. Look at Delete clip or Undo."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Preferences → Capture. Write Timeout on or off.","With Timeout on, play pads, wait without tapping Capture. Confirm the buffer dies.","Turn Timeout off. Play, wait, tap Capture. Notes should still be there.","Restore the setting you want for future sessions.","If VoiceOver is on, note the RN exception.","Add this pair to your error card: “buffer died after pause → Timeout.”"],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the default? <strong>Answer:</strong> Timeout on — buffer clears after you stop (Manual §2.4.2).","Does Timeout wipe overdubs into an existing clip? <strong>Answer:</strong> No.","What else clears the buffer immediately? <strong>Answer:</strong> The X control."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §2.4.2 Capture Timeout","RN 1.0.12 Capture Timeout; VoiceOver disables timeout","Capture in Note: X to clear","Ableton Note.md Preferences Capture"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. Reproduce on/off once. Line added to the error card."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-1</code></em>"}]}],"minutes":8},{"id":"note-l13-2-2","title":"13.2.2 — First capture sets unwanted tempo → set tempo first or re-tap","blocks":[{"type":"step","title":"13.2.2 — First capture sets unwanted tempo → set tempo first or re-tap","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Stop the first Capture from rewriting tempo — or recover with Set Settings after it does."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"If transport is <strong>stopped</strong> and you Capture the <strong>first</strong> clip, Note <strong>extracts tempo</strong> from your playing (Manual §8.1.1–8.1.2; FAQ). That is a feature. It is a problem when you already wanted 90, 120, or any number you chose."},{"type":"prose","html":"Fixes (sourced): set tempo <strong>before</strong> that first Capture (slider, ±1, <strong>Tap Tempo</strong> — four taps then continuous). Or let it extract, then open <strong>Set Settings → Tempo</strong> and correct it. Later Captures with transport running do not use the first-capture extract rule the same way — they follow the Set tempo and the shortest-clip length rule."},{"type":"prose","html":"Note 2.0.1 remembers last key/tempo on new Sets. An inherited tempo can also surprise you. Check Tempo on <strong>+ New</strong>."},{"type":"prose","html":"2.x empty Sets no longer auto-enable the metronome; a count-in plays instead (RN 2.0.1). That is not a tempo bug."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["New Set. Leave tempo untouched. Transport stopped. Play unevenly and Capture. Read Tempo.","Undo or delete the clip. Set Tempo with Tap Tempo or the slider.","Capture again with transport stopped or after Play. Confirm tempo holds.","Write the rule: “first stopped Capture sets tempo.”","Add it to the error card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["When does Capture set tempo? <strong>Answer:</strong> First clip, transport stopped (Manual; FAQ).","How do you set tempo without Capture? <strong>Answer:</strong> Set Settings → Tempo: slider, ±1, Tap Tempo.","Does every later Capture rewrite tempo? <strong>Answer:</strong> The documented extract is the first stopped Capture."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §5.2; §8.1.1–8.1.2","Note FAQ: select tempo","RN 2.0.1 last tempo remembered; metronome/count-in","Lesson 12.1.1"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. One unwanted extract, one correction. Card updated."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-2</code></em>"}]}],"minutes":8},{"id":"note-l13-2-3","title":"13.2.3 — Create Clip longer than expected → shortest clip rule when transport runs","blocks":[{"type":"step","title":"13.2.3 — Create Clip longer than expected → shortest clip rule when transport runs","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Explain a surprisingly long (or short) new clip by checking transport state and the shortest existing clip."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"<strong>Stopped</strong> Free Length: play up to <strong>8 bars</strong>, tap <strong>Capture</strong> — clip follows that performance (within the 8-bar buffer)."},{"type":"prose","html":"<strong>Running</strong> with other clips: the button is <strong>Create Clip</strong>. New clips have <strong>at least as many bars as the shortest clip already in the Set</strong> (Manual §8.1.2). If your shortest clip is 8 bars, you will not get a 1-bar bass clip this way. If you wanted 1 bar, either stop transport and Capture a short idea, use Fixed Length plus icon <strong>1</strong>, or crop the loop brace afterward (max still 16)."},{"type":"prose","html":"Fixed Length always uses the plus-icon length you picked (1/2/4/8/16)."},{"type":"prose","html":"This is not a tempo bug and not Timeout."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Make a 4-bar drum clip (Fixed Length 4).","Start transport. Free Length a short bass riff. Create Clip.","Measure the new clip. It should be ≥ 4 bars.","Crop or recapture Fixed Length 1 if you needed a bar.","Write “running + Create Clip ≥ shortest clip” on the card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the running-transport length rule? <strong>Answer:</strong> New clip ≥ shortest existing clip.","What is the stopped Free Length cap? <strong>Answer:</strong> Up to 8 bars.","How do you force 1 bar while drums play? <strong>Answer:</strong> Fixed Length plus icon → 1 (then Add), or crop after."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §8.1.1–8.1.2","Capture in Note: Free Length running vs stopped","FAQ: 16-bar max","Ableton Note.md Free Length behaviors"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. Reproduce the ≥ shortest-clip result. Card updated."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-3</code></em>"}]}],"minutes":8},{"id":"note-l13-2-4","title":"13.2.4 — Automation won’t reset default → delete automation first","blocks":[{"type":"step","title":"13.2.4 — Automation won’t reset default → delete automation first","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"When Return to Default is greyed, delete that parameter’s automation, then reset."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Automated parameters show a <strong>dot</strong>. <strong>Return to Default</strong> (parameter menu or double-tap reset) is <strong>greyed</strong> while automation exists (Manual §7.5.1). This is not a broken knob."},{"type":"prose","html":"Fix: tap the parameter name → <strong>Delete</strong> automation. Then Return to Default / double-tap works. <strong>Insert</strong> writes a straight line at the current value — it does not restore the preset default by itself."},{"type":"prose","html":"Dotted line = pending. If you never tapped <strong>Add</strong>, <strong>X</strong> keeps the previous solid curve (or none). Transport must be running to capture new automation."},{"type":"prose","html":"Do not confuse this with Groove Amount or mixer volume. Double-tap reset on a fader is RN 1.0.15 and is separate unless that fader is automated."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Automate a filter or macro (transport on, move, Add). Confirm the dot.","Open the parameter menu. Confirm Return to Default is greyed.","Delete automation. Reset the knob.","Optionally Insert a straight line if you wanted a static automated value instead of the preset default.","Add the pair to the card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why is Return to Default greyed? <strong>Answer:</strong> That parameter has automation.","What removes it? <strong>Answer:</strong> Parameter menu → Delete.","Does X delete stored automation? <strong>Answer:</strong> X discards a pending (dotted) pass, not the stored solid line."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §7.5; §7.5.1","Capture in Note: Automation","RN 1.0.15 double-tap reset","Note FAQ: automation via Capture"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Six minutes. Greyed → Delete → reset. Card updated."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-4</code></em>"}]}],"minutes":8},{"id":"note-l13-2-5","title":"13.2.5 — Cloud set missing → account/email/Live version","blocks":[{"type":"step","title":"13.2.5 — Cloud set missing → account/email/Live version","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Run the official Cloud-missing checklist before you re-upload forever."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"If synced Sets do not appear under Live’s <strong>Cloud</strong> label (KB <em>Note Sets in Ableton Cloud not Appearing in Live</em>):"},{"type":"list","items":["<strong>Internet</strong> on the phone (Wi-Fi or Note allowed under Mobile Data). Uploads can take seconds to minutes.","Cloud <strong>enabled in Note and in Live</strong>. Same <strong>Ableton account email</strong> as the Live license.","<strong>Re-enable:</strong> toggle Cloud off/on in Note (browser login). In Live, sign out of Cloud, sign in again. Use the main account; “Go to Ableton.com” → log out if the browser is on the wrong user.","<strong>Cloud server status</strong> (Ableton Status Page)."],"ordered":true},{"type":"prose","html":"Also required: Live <strong>≥ 11.2.5</strong>, <strong>Show Cloud</strong> in Live Library settings. Sync may look finished in Note while Live is still downloading (Troubleshooting Problems with Note Files). Disabling Cloud on iOS does not remove already-synced Sets from Live; only full opt-out via the Ableton account removes Cloud data (same KB)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm Live version ≥ 11.2.5 and Show Cloud is on.","Confirm Note Cloud toggle and the email you used.","If still empty, re-enable both sides with the same email.","Check the Status Page if both logins are correct.","Wait through a large Set’s download.","Write the step that fixed it (or that the server was down)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What email must match? <strong>Answer:</strong> The Ableton account on Note Cloud and the Live license.","What Live version is the floor? <strong>Answer:</strong> 11.2.5.","Can Note upload with all data radios off? <strong>Answer:</strong> No. It queues until Wi-Fi or allowed mobile data exists."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Sets in Ableton Cloud not Appearing in Live","Troubleshooting Problems with Note Files","Note FAQ: Cloud missing; same email; 8 Sets","Note Compatibility; Manual §2.1, §10.1"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Checklist ticked against your real accounts. Card updated."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-5</code></em>"}]}],"minutes":8},{"id":"note-l13-2-6","title":"13.2.6 — Sample missing after delete → warnings; restore from Files/backup","blocks":[{"type":"step","title":"13.2.6 — Sample missing after delete → warnings; restore from Files/backup","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Treat a missing-sample warning as a file problem: restore the Note Set or the collected Live Project, not a new recording first."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN / Level 9 path: Note can warn when a sample is missing after delete. FAQ: back up the entire <strong>Ableton Note</strong> folder (Files → On My iPhone/iPad → Ableton Note) before deleting the app. Projects hold Sets; User Library holds Imported / Recordings."},{"type":"prose","html":"In Live, if the <strong>original Note Set was removed from Cloud</strong>, samples can go missing. KB fix: quit Live, re-add the Set to Cloud from the iOS local copy, reopen Live, then Collect All and Save. If User Library lives on a disconnected external drive, reconnect it."},{"type":"prose","html":"Share To… .ablbundle is the portable backup. Cloud is not."},{"type":"prose","html":"{type:'gap'} Extracts do not give a per-sample “Restore” button inside Note. You restore from Files, iOS backup, Cloud re-upload, or the collected Live Project."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["If Live reports missing files: confirm the Note Set still exists locally. Re-upload to Cloud. Collect All and Save.","If Note warns after a pad delete: look in Libraries → Current Set → Recordings and User Library → Recordings / Imported.","If the app was deleted: restore the Ableton Note folder from your backup.","Do not rely on an empty Cloud slot.","Add the pair to the card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What Live step prevents this next time? <strong>Answer:</strong> Collect All and Save immediately.","Where are local Note files? <strong>Answer:</strong> Files → On My iPhone/iPad → Ableton Note (Projects + User Library).","Is Cloud the restore disk? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ: file locations; backup before delete; Collect All and Save","Troubleshooting Problems with Note Files","Working with Samples in Note (paths)","Manual §10.1"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. Verify your Ableton Note folder exists and one Set is also bundled or collected. Card updated."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-6</code></em>"}]}],"minutes":8},{"id":"note-l13-2-7","title":"13.2.7 — Bluetooth unplayable lag → wired","blocks":[{"type":"step","title":"13.2.7 — Bluetooth unplayable lag → wired","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Treat unplayable pad delay on wireless headphones as expected Bluetooth latency and switch to wired."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Bluetooth headphones (including AirPods) add <strong>34–200 ms</strong>. Wired averages <strong>5–10 ms</strong> (Bluetooth Headphones and Latency in Note). FAQ recommends wired for playing instruments. Note may show a Bluetooth delay warning (RN 1.0.12 “Don’t show again”)."},{"type":"prose","html":"This is not a Capture bug, not Link, and not a slow device. Newer Bluetooth can help but is limited by the phone’s radio (same KB). If you suspect abnormal BT behavior, unpair in iOS Settings → Bluetooth and pair again — that is the KB’s only extra step."},{"type":"prose","html":"Audio output that is <strong>silent</strong> (not late) is a different KB: iOS <strong>Sound Recognition</strong> can interfere (Troubleshooting Audio Output on Note). Turn that off if playback is missing."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Play pads on Bluetooth. Notice the gap.","Plug in wired headphones (adapter if needed). Play the same pads.","Write the two feels. Keep wired for Capture.","If audio is gone entirely, disable Sound Recognition and retest.","Add “lag → wired; silence → Sound Recognition” to the card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What latency range does Ableton cite for Bluetooth headphones? <strong>Answer:</strong> 34–200 ms vs 5–10 ms wired.","Does unpairing always fix musical timing? <strong>Answer:</strong> Only if the headphones are abnormal; codec latency remains.","Is this the same as Bluetooth MIDI? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Bluetooth Headphones and Latency in Note","Note FAQ: Bluetooth headphones","RN 1.0.12 Bluetooth delay warning","Troubleshooting Audio Output on Note (Sound Recognition)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Five minutes. Wired vs Bluetooth A/B. Card updated."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-7</code></em>"}]}],"minutes":8},{"id":"note-l13-2-8","title":"13.2.8 — Live format warning historical → update Note; re-save","blocks":[{"type":"step","title":"13.2.8 — Live format warning historical → update Note; re-save","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"If Live says the Note document is a newer file format, update Note and re-save the Set — do not chase a Live upgrade for this historical bug."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN <strong>1.1.1</strong>: fixed Live warning <strong>“This document is in a new file format version”</strong> caused by <strong>incorrect metadata from Note</strong>. <strong>Re-save affected Sets from updated Note.</strong> <strong>No Live update required.</strong>"},{"type":"prose","html":"This is a Note-side metadata bug, not proof that you need Live 12 Suite. Still honor the real floor: Live <strong>11.2.5+</strong> for opening Note Sets / Cloud."},{"type":"prose","html":"If you already run Note ≥ 1.1.1 and still see format errors, {type:'gap'} the extracts do not list a later recurrence. Then use Share To… a fresh .ablbundle, or contact Support with version + steps (FAQ bug report). Also check the macOS double-transfer filename bugs (Troubleshooting Problems with Note Files) — those look like “can’t open,” not this exact warning."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Note Settings → Help: write the version. Update via App Store if below 1.1.1.","Open the affected Set in updated Note (any small edit or re-upload).","Transfer again (Cloud or Share To…).","Open in Live. The historical warning should be gone.","Add the pair to the card: “format version warning → update Note, re-save; not a Live update.”"],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which Note version fixed the metadata warning? <strong>Answer:</strong> 1.1.1.","Do you need a newer Live for that specific warning? <strong>Answer:</strong> No (RN 1.1.1).","What is the actual Live compatibility floor? <strong>Answer:</strong> 11.2.5."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.1.1","Note Compatibility: 11.2.5+","Troubleshooting Problems with Note Files (can’t open / filename)","Note FAQ: bug reports; version path"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Six minutes. Version checked. Card updated. Re-save any old Set you still open in Live."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-8</code></em>"}]}],"minutes":8},{"id":"note-l13-2-9","title":"13.2.9 — Can’t open Live Set in Note → expected one-way limit","blocks":[{"type":"step","title":"13.2.9 — Can’t open Live Set in Note → expected one-way limit","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Recognize a Live Set that will not open in Note as the documented one-way limit, not a corrupt file."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"FAQ: <strong>Live Sets cannot currently be opened in Note.</strong> Manual §10.1: sharing works Note → Live only. Compatibility: Sets created or saved in Live cannot be opened in Note. Cloud will not pull a Live Project onto the phone."},{"type":"prose","html":"If a file will not open, ask: is it <strong>.als</strong> / a Live Project, or a Note <strong>.ablbundle</strong> / Cloud Note Set? Bundles open in Note or Live 11.2.5+. Live Saves do not open in Note."},{"type":"prose","html":"macOS Share To… name bugs can also block a <strong>bundle</strong> (number after extension, missing <code>.ablbundle</code>). That is a different KB and a rename fix."},{"type":"prose","html":"Do not file this one-way limit as a crash. Do not wait for a two-way Cloud that the extracts do not promise."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Identify the file extension (.als vs .ablbundle vs Cloud Note Set).","If it is a Live Set, stop. Use the Note duplicate you kept, or sketch a new Note Set.","If it is a bundle that will not open, rename per Troubleshooting Problems with Note Files.","Write the one-way sentence on the error card.","Confirm your capstone still has a Note-side copy."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Can Cloud send Live Projects to Note? <strong>Answer:</strong> No.","What Note-origin file can another phone open? <strong>Answer:</strong> .ablbundle or a Cloud Note Set on the same account.","Is this the 1.1.1 format warning? <strong>Answer:</strong> No. That warning was Note metadata into Live."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ: no Live→Note","Ableton Note Manual §10.1","Note Compatibility","Troubleshooting Problems with Note Files","Lesson 12.8.6"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Five minutes. File-type check on one transfer. Card updated."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-9</code></em>"}]}],"minutes":8},{"id":"note-l13-2-10","title":"13.2.10 — Build personal error→fix cheatsheet","blocks":[{"type":"step","title":"13.2.10 — Build personal error→fix cheatsheet","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.2 — Error library (sourced)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Collapse 13.2.1–13.2.9 plus Appendix C into one page you can read mid-session."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Practice: a personal one-page error card. Use only sourced pairs:"},{"type":"table","headers":["Symptom","First fix"],"rows":[["Buffer vanished after pause","Capture Timeout / VoiceOver exception"],["Tempo jumped on first clip","Set tempo first or Tap Tempo after"],["New clip too long","Transport running → shortest-clip rule"],["Can’t reset a knob","Delete automation"],["Cloud empty in Live","Email, Show Cloud, 11.2.5, re-login, status, wait"],["Sample missing","Files/backup; re-Cloud; Collect All and Save"],["Late pads on AirPods","Wired (34–200 ms)"],["Live “new file format”","Note ≥ 1.1.1, re-save"],["Live Set won’t open in Note","Expected one-way"],["Orange mic","Expected"],["Upload stuck","Network, 100 MB, 8 slots, status"],["Crash","Auto report; update; log version"],["No audio","Sound Recognition off"]],"caption":null},{"type":"prose","html":"Do not add forum myths. Appendix C is the official card; this page is yours."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Copy the table by hand. Delete rows you have never hit if you need space; keep the one-way and Timeout rows.","Add your Note version and Ableton email (the one that must match Live).","Photograph the page into the same album as Maps A–E.","Keep it in the case with the wired headphones.","After the next real failure, add a date, not a new un-sourced fix."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where does the official course card live? <strong>Answer:</strong> Appendix C (and this module’s lessons).","May you add a “reset all settings” ritual? <strong>Answer:</strong> Only if a source states it. These extracts do not.","What version belongs on the card? <strong>Answer:</strong> Settings → Help."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Lessons 13.2.1–13.2.9","Appendix C table (syllabus)","FAQ; RNs; Cloud/Bluetooth/Files KBs","Syllabus 13.2 practice"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Fifteen minutes. One photographed cheatsheet."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-2-10</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-13-3-103","code":"13.3","title":"13.3","blurb":"13.3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l13-3-1","title":"13.3.1 — Shared DNA: Session clips, scenes, Capture idea, Drift/Wavetable family, Cloud","blocks":[{"type":"step","title":"13.3.1 — Shared DNA: Session clips, scenes, Capture idea, Drift/Wavetable family, Cloud","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.3 — Comparison: Note vs Live (honest)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Name the five shared ideas so Note feels like Live’s sketchbook, not a random iOS toy."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Shared DNA (from the extracts, not marketing fluff):"},{"type":"list","items":["<strong>Session clips</strong> — Note’s only grid is Session: tracks vertical, scenes horizontal, same mental model as Live Session (Manual §4; Ableton Note.md).","<strong>Scenes</strong> — a row launches together (max 8 in Note).","<strong>Capture</strong> — Live users know Capture; Note records MIDI by Capture only (FAQ).","<strong>Drift / Wavetable family</strong> — Note devices are Live-family instruments; presets move to Live via the Set (Using Note Presets in Live). Wavetable may lock in non-Suite Live.","<strong>Cloud</strong> — Note Sets appear in Live’s browser Cloud (11.2.5+)."],"ordered":false},{"type":"prose","html":"Note is still <strong>not</strong> mobile Live: no Arrangement, no AUv3, 8 tracks, no Live→Note. Shared DNA is why the hand-off works. It is not a feature-parity claim."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write the five bullets from memory.","Open a Note Set and point at clips, a scene number, Capture, a Drift or Wavetable track.","Open the same Set in Live (or recall Map B) and point at the same five.","Write one sentence: “Same Session language; different ceilings.”","Keep this page next to 13.3.2–13.3.3."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Does shared Session DNA mean Note has Arrangement? <strong>Answer:</strong> No.","Why can Standard open a Note Wavetable track at all? <strong>Answer:</strong> The Set brings a locked rack with Note macros (Using Note Presets in Live).","Is Capture optional in Note MIDI recording? <strong>Answer:</strong> MIDI recording happens via Capture (FAQ)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §4, §8.1, §10.1","Ableton Note.md Session vs Arrangement","Note FAQ: Capture; Cloud","Using Note Presets in Live","Course syllabus 13.3: Note does not replace Live"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. Five shared-DNA bullets written."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-3-1</code></em>"}]}],"minutes":8},{"id":"note-l13-3-2","title":"13.3.2 — Note strengths: speed, portability, constraint creativity","blocks":[{"type":"step","title":"13.3.2 — Note strengths: speed, portability, constraint creativity","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.3 — Comparison: Note vs Live (honest)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"List three jobs Note should keep even after you own Live."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Sourced strengths, not slogans:"},{"type":"list","items":["<strong>Speed</strong> — + New with three tracks; Capture after you play; auto-save every 10–15 seconds; screen stays awake in foreground (FAQ; RN 1.0.15). Beatmaking 80/20: main parts arrive quickly.","<strong>Portability</strong> — iPhone/iPad, iOS 15+; sample the environment; export audio from the device; Link on a local network.","<strong>Constraint creativity</strong> — 8 tracks, 8 scenes, 16-bar clips, two FX, no Arrangement. Beatmaking: limitations focus the mind. Level 12.8 treated those ceilings as drills."],"ordered":false},{"type":"prose","html":"Note is a playable sketchbook (Manual welcome; Ableton Note.md). Keep jobs that die when you “just wait until the studio”: field samples, two-minute Capture, scene hooks, Link jams."},{"type":"prose","html":"Do not call Note cheap Live. Cost is App Store + bundled Live Lite; Live license is separate."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write three Note-only jobs you actually did in Level 12.","Match each to speed, portability, or constraint.","Write one job you will <strong>not</strong> move to Note next time (preview 13.3.3).","Keep the list for 13.3.5."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Name one sourced speed fact. <strong>Answer:</strong> Capture after playing; or auto-save 10–15 s; or default three tracks.","Name one sourced constraint. <strong>Answer:</strong> 8 tracks / 8 scenes / 16 bars / two FX / no MIDI I/O.","Is “Note replaces Live on tour” a course claim? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Manual welcome; §3.1 + New","Note FAQ: auto-save; iOS; Capture","RN 1.0.15 screen awake","Beatmaking: limitation; 80/20","Ableton Note.md sketchbook"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. Three Note jobs listed."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-3-2</code></em>"}]}],"minutes":8},{"id":"note-l13-3-3","title":"13.3.3 — Live strengths: Arrangement, deep devices, mixing, routing, plugins","blocks":[{"type":"step","title":"13.3.3 — Live strengths: Arrangement, deep devices, mixing, routing, plugins","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.3 — Comparison: Note vs Live (honest)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Name the Live jobs this course will not pretend Note can do."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Live-only (or Live-deep) relative to the Note extracts:"},{"type":"list","items":["<strong>Arrangement View</strong> — Note has none. Export is only scenes top to bottom.","<strong>Deep devices</strong> — Note shows preset subsets and macros. Full Wavetable is Suite/Pack; Note Wavetable in Standard is locked. Drift’s extra pages may be IAP/manual-conflict on Note.","<strong>Mixing</strong> — Note mixer is M/S/volume, up to two Main FX. Not a Live mix.","<strong>Routing</strong> — {type:'gap'} Note extracts do not document Live sends/buses. Pointer: Live course.","<strong>Plugins / AUv3</strong> — Note cannot host AUv3 (FAQ: Windows compatibility). Plugins start after hand-off."],"ordered":false},{"type":"prose","html":"Collect All and Save, User Library presets, and Arrangement recording belong here. Sister course: Ableton Live 12."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write five Live strengths as a list (Arrangement, deep devices, mix, routing, plugins).","Next to each, write the Note ceiling that blocks it.","Do not open a plugin in this lesson unless you already have a collected Set — and even then, only to observe, not to mix the capstone.","Keep the list for 13.3.5."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why no AUv3 in Note? <strong>Answer:</strong> FAQ: it would break Live-on-Windows compatibility for Sets.","What happens to Note Wavetable in Live Standard? <strong>Answer:</strong> Locked rack, macros only.","Can two Main FX replace a Live mix? <strong>Answer:</strong> No. They are a Note ceiling (RN 1.0.15)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note.md: not mobile Live; no Arrangement","Note FAQ: AUv3; Live editions; warp","Using Note Presets in Live","RN 1.0.15 Main FX","Syllabus sister-course table"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. Five Live jobs with the matching Note ceiling."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-3-3</code></em>"}]}],"minutes":8},{"id":"note-l13-3-4","title":"13.3.4 — What not to force in Note","blocks":[{"type":"step","title":"13.3.4 — What not to force in Note","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.3 — Comparison: Note vs Live (honest)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Write a stop list of productions you will not finish inside Note."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Do not force in Note:"},{"type":"list","items":["A linear album sequence (no Arrangement; 8 scenes; 16-bar clips)","Third-party instruments/effects (no AUv3)","MIDI file exchange with non-Live tools","Pitch-bend / MPE / sustain performances","Independent time-stretch on <strong>Sampler/Drum Rack</strong> (FAQ warp). Use 2.x <strong>audio tracks</strong> if you have them, or Live","Two-way Cloud revisions with a Live-only mix","Android","A nine-track stack","Finishing a mix for release on two Main FX and phone speakers"],"ordered":false},{"type":"prose","html":"Force <em>is</em> allowed: one-hour sketches, field kits, Link jams, controller macros, scene hooks. When a task hits the stop list, switch to Map B."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Copy the stop list in your own words (eight bullets).","Star any item you already tried to force in Level 12.","Write the exit: Cloud / bundle → Collect All and Save.","Keep this with 13.3.5."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Is a 16-bar clip a song? <strong>Answer:</strong> No. It is the clip ceiling.","Can you warp a Drum Rack hit’s time without changing pitch (pre-2 sampler path)? <strong>Answer:</strong> No (FAQ).","What is the exit ramp? <strong>Answer:</strong> Map B."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ limits","Manual Session / Cloud","RN 2.0.1 audio warp contrast","Beatmaking: sketch vs finish","Course syllabus 13.3: what not to force in Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Eight minutes. Personal stop list written."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-3-4</code></em>"}]}],"minutes":8},{"id":"note-l13-3-5","title":"13.3.5 — Hand-off criteria checklist","blocks":[{"type":"step","title":"13.3.5 — Hand-off criteria checklist","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.3 — Comparison: Note vs Live (honest)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Decide in one minute whether a Set stays in Note, parks, or takes Map B."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Practice for 13.3: three jobs for Note-only and three for Live-only. Use this checklist:"},{"type":"prose","html":"<strong>Stay in Note</strong> if the idea is still a sketch, memorable test not done, you need another scene, or you only need a bounce (Map A)."},{"type":"prose","html":"<strong>Park</strong> if nothing is memorable after a delay (Beatmaking). Share To… once if you might regret delete."},{"type":"prose","html":"<strong>Hand off (Map B)</strong> if you need Arrangement, more than 8 tracks, plugins, independent sampler warp, a mix, or collaborator-in-Live. Then: Cloud or bundle, Live 11.2.5+, Collect All and Save, origin card."},{"type":"prose","html":"Never hand off because you are bored of pads — finish the idea first (Beatmaking: finish the idea before mixing)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Pick three old lab Sets.","Mark each stay / park / hand off with one checklist reason.","Write three Note-only jobs and three Live-only jobs (module practice).","If one Set is a hand-off, confirm collect already happened or schedule 13.4.3.","Store the page with Maps A–B."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the first Live action after hand-off? <strong>Answer:</strong> Collect All and Save.","Why wait before park vs keep? <strong>Answer:</strong> Beatmaking delay / memorable test.","Does a bounce replace hand-off when you need Arrangement? <strong>Answer:</strong> No. A bounce is audio; Arrangement needs the Set in Live."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Beatmaking: delay; memorable; finish idea before mixing","Manual §10.1; FAQ Cloud / limits","Lessons 13.3.1–13.3.4","Syllabus 13.3 practice"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Three Sets triaged + 3+3 job lists."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-3-5</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-13-4-104","code":"13.4","title":"13.4","blurb":"13.4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l13-4-1","title":"13.4.1 — Weekly: 5 sketches, rate next week","blocks":[{"type":"step","title":"13.4.1 — Weekly: 5 sketches, rate next week","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.4 — Ongoing practice system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Plan five short Note sketches this week and a rating pass next week, using Beatmaking’s delay."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Beatmaking: store raw ideas, separate create from judge, give it a week, keep them in folders, 80/20, keep what is memorable. Course Level 11.3 already named a daily 10–20 minute ritual. This lesson makes the weekly unit: <strong>five</strong> sketches, <strong>rate next week</strong>."},{"type":"prose","html":"Each sketch: working title, Capture something, at least one scene, auto-save will keep it (10–15 s). Do not mix. Do not Cloud all five (8 slots). Local + optional Share To… weekly archive."},{"type":"prose","html":"Rating (next week): memorable yes/no, keep / park / delete (after a backup), one candidate for Live (13.4.3). Ask someone who is not a producer if you want the “randos” test (Beatmaking)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Put five 15-minute blocks on a calendar for the next 7 days.","Put one rating block on day 8–14.","Name a folder convention (see 13.4.5).","After sketch 1 this week, stop. Do not rate it today.","Write the rule on the calendar: “rate next week.”"],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why not rate tonight? <strong>Answer:</strong> Beatmaking: space between create and judge; a week is their example.","How many Cloud slots should five sketches consume? <strong>Answer:</strong> Prefer zero until one earns a slot (8-slot ceiling).","What is the 80/20 reminder? <strong>Answer:</strong> Main parts come fast; do not fine-tune until it is a keeper."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Beatmaking: time, organize, 80/20, memorable, randos","Note FAQ: auto-save; 8 Cloud Sets","Syllabus 11.3 daily ritual; 13.4 practice (30-day calendar)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Five blocks + one rating block on the calendar."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-4-1</code></em>"}]}],"minutes":8},{"id":"note-l13-4-2","title":"13.4.2 — Monthly: Cloud curation day","blocks":[{"type":"step","title":"13.4.2 — Monthly: Cloud curation day","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.4 — Ongoing practice system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Schedule one monthly hour to rotate the eight Cloud slots against what Live actually needs."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Eight Sets. Move and Push Sets can occupy slots too (Manual: Cloud stores Note and Move Sets). Multi-device same account. Curation day: evict anything Live already collected or that you only needed last month. Archive with Share To… first."},{"type":"prose","html":"Check 100 MB warnings, illegal-looking names if upload failed ({type:'gap'} no official illegal-character list in extracts — simplify names if rejected), and Cloud status if a slot will not clear."},{"type":"prose","html":"Hero Sets (13.5.2) may stay. Everything else is a queue."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Put a monthly recurring hour on the calendar.","This month: count Cloud Sets. For each, mark live-needed / collected / archive-and-evict.","Share To… then remove evictions.","Upload at most the Sets that must appear in Live this month.","Write n/8 in your notes."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many Cloud Sets? <strong>Answer:</strong> Eight (RN 1.2 raised from 5).","First step before evict? <strong>Answer:</strong> Share To… or confirm Collect All and Save.","Do Move Sets count? <strong>Answer:</strong> Cloud holds Note and Move Sets (Manual §2.1)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ: 8 Sets; not backup","Manual §2.1 Cloud; Move Sets appear","RN 1.2","Sharing Note Sets","Lesson 12.8.4"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Monthly block created. Current n/8 written."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-4-2</code></em>"}]}],"minutes":8},{"id":"note-l13-4-3","title":"13.4.3 — Monthly: one full Live hand-off finish","blocks":[{"type":"step","title":"13.4.3 — Monthly: one full Live hand-off finish","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.4 — Ongoing practice system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Once a month, take one keeper all the way through Map B and start the Live finish, not another Note polish."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Monthly unit: <strong>one</strong> Set. Not five Cloud dumps. Path: memorable after delay → Cloud or .ablbundle → Live 11.2.5+ → Collect All and Save → Arrangement / mix in the Live course. Note work stops except a duplicate if you still want a mobile sketch (which will diverge)."},{"type":"prose","html":"If you own only Note on a phone this month, the “finish” is still collect on any available Live (including Lite that ships with Note). If you have no computer, {type:'gap'} you cannot complete hand-off; bounce (Map A) and retry next month."},{"type":"prose","html":"Do not confuse Link Audio with this finish."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Calendar: one 90-minute monthly hand-off block.","Pick the Set that survived last week’s rating.","Run Map B. Origin card. Collect All and Save.","Write the first Live job (Arrangement, extra track, or mix) — then do that in the Live course, not here.","Evict the Cloud slot if the Project is collected and you need space."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many full hand-offs per month does this lesson ask for? <strong>Answer:</strong> One.","What is the mandatory Live command? <strong>Answer:</strong> Collect All and Save.","Can you finish Arrangement in Note that day? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Map B sources (Manual §10.1; FAQ; Compatibility)","Beatmaking: memorable; finish later","Lesson 13.3.5 checklist","Get Ableton Live Lite (FAQ)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Monthly hand-off block + named candidate Set."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-4-3</code></em>"}]}],"minutes":8},{"id":"note-l13-4-4","title":"13.4.4 — After each Note app update: read release notes; re-check version gate labs","blocks":[{"type":"step","title":"13.4.4 — After each Note app update: read release notes; re-check version gate labs","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.4 — Ongoing practice system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"When Note updates, read the official notes and re-test only the gates that version changed."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Version lives in Settings → <strong>Help</strong>. Release notes: Help link or https://www.ableton.com/en/release-notes/note/. Auto-update may apply overnight (iOS App Store setting)."},{"type":"prose","html":"After an update, do not re-do the whole course. Re-check labs that were version-gated: Slice (1.7.2), Reverse (1.0.12), audio tracks / Link Audio / Auto Shift / Erosion / monitoring-in-track (2.0.1), Auto Filter (1.4), MIDI Editor pack (1.3), Cloud 8 / Move share (1.2). Appendix D is the cheat sheet."},{"type":"prose","html":"Known conflict to re-read if you use samples: FAQ still says warping is not available (sampler path); 2.0.1 audio tracks <strong>are</strong> warped. Teach both."},{"type":"prose","html":"Log the new version on the next process card. Re-save Sets if a RN tells you to (see 1.1.1)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write today’s version from Help.","Open official release notes. List features newer than your last logged version.","Pick one gated lab to re-open (for example 12.4.2 Slice or 12.6.4 Link Audio).","Update your error card if a bugfix matches a row (format warning, etc.).","Calendar: “after each Note update → this lesson.”"],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where are official notes? <strong>Answer:</strong> Help, or ableton.com/en/release-notes/note/.","Do you re-take Gate J after every update? <strong>Answer:</strong> No. Re-check the gates that version changed.","Sampler warp vs audio-track warp — still both true? <strong>Answer:</strong> Yes, dated: FAQ path vs RN 2.0.1."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ: version; auto-update; release notes URL","Manual §2.5 Help","Note Release Notes","Appendix D conflicts"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes after the next update (or now, once). Version + one re-checked lab noted."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-4-4</code></em>"}]}],"minutes":8},{"id":"note-l13-4-5","title":"13.4.5 — Portfolio folder structure on device + computer","blocks":[{"type":"step","title":"13.4.5 — Portfolio folder structure on device + computer","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.4 — Ongoing practice system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Build a two-place folder plan that matches how Note actually stores files."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"<strong>Device (sourced paths):</strong>"},{"type":"list","items":["Files → On My iPhone/iPad → <strong>Ableton Note → Projects</strong> (Sets)","<strong>User Library → Imported</strong> / <strong>Recordings</strong> (and Drum Sampler / Melodic Sampler subfolders when saved)","Your <strong>Share To…</strong> destination (Files, iCloud Drive) for .ablbundle backups","Photos for artwork and screen recordings"],"ordered":false},{"type":"prose","html":"<strong>Computer:</strong> Live Projects after Collect All and Save; a sibling folder for .ablbundle archives and bounces (WAV/M4A). Cloud in Live’s browser is not that archive."},{"type":"prose","html":"{type:'gap'} Ableton does not publish a required “DDW Portfolio” tree. Use names you will still understand: <code>Note-Projects-backup</code>, <code>Bounces</code>, <code>Live-from-Note</code>. Artwork is a memory aid (course 11.3.3), not a folder engine."},{"type":"prose","html":"Back up the whole Ableton Note folder before deleting the app (FAQ)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On the device, open Files and photograph the Ableton Note tree.","Create <code>Bounces</code> and <code>Bundles</code> folders in Files (or on the Mac).","Move one export and one .ablbundle into those folders.","On the computer, write the path of one collected Live Project.","Add this map to the portfolio index (13.5.1)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do local Sets live? <strong>Answer:</strong> Ableton Note → Projects.","Where do unsaved recordings of the current Set live in the browser? <strong>Answer:</strong> Libraries → Current Set → Recordings.","Is Cloud a third archive disk? <strong>Answer:</strong> No. Transfer only."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ: Files paths; backup before delete","Working with Samples in Note: storage locations","Sharing Note Sets","Manual §10.1 Collect All and Save"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Fifteen minutes. Device + computer paths written and one file in each archive folder."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-4-5</code></em>"}]}],"minutes":8},{"id":"note-l13-4-6","title":"13.4.6 — Graduation criteria: Gates A–J complete + 10 archived sketches","blocks":[{"type":"step","title":"13.4.6 — Graduation criteria: Gates A–J complete + 10 archived sketches","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.4 — Ongoing practice system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"State graduation as two piles: every gate checklist you can still score, plus ten sketches that exist outside the app’s mood."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Syllabus: graduation = <strong>Gates A–J complete + 10 archived sketches</strong>. Gates are self-score checklists from prior sourced facts. You do not need a fake certificate screen."},{"type":"prose","html":"<strong>Archived</strong> means Share To… / Files / collected Live / bounce — not “still only in RAM.” Auto-save keeps Projects, but deleting the app without a backup kills them (FAQ). Ten sketches can include Level 12 labs. They should survive a week’s delay (Beatmaking)."},{"type":"prose","html":"If a gate is incomplete, return to that level. If you have ten loops and no Gate J package, you have not graduated this course."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["List Gates A–J. Mark done / missing from memory of each checkpoint.","Count archived sketches (bundles, bounces, collected Sets). Target 10.","If under 10, schedule 13.4.1 weeks until you get there.","If Gate J is missing, return to 12.10.","Write a one-line graduation status."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What two piles define graduation here? <strong>Answer:</strong> Gates A–J complete, and 10 archived sketches.","Does Cloud holding 8 Sets equal 10 archives? <strong>Answer:</strong> No. Archive is Files/Live/bounce; Cloud is 8 transfer slots.","Who grades the gates? <strong>Answer:</strong> You, against the sourced checklists."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Syllabus 13.4.6","Note FAQ: backup; Cloud not archive","Beatmaking: delay; organize","Module 12.10 Gate J package"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Ten minutes. Status line written: gates /10 sketches."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-4-6</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-13-5-105","code":"13.5","title":"13.5","blurb":"13.5","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l13-5-1","title":"13.5.1 — Index all course Sets with version + gate tags","blocks":[{"type":"step","title":"13.5.1 — Index all course Sets with version + gate tags","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.5 — Capstone portfolio index</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Make a written index of every course Set: name, Note version, gate, and where the file lives."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"FAQ: Cloud holds <strong>eight</strong> Sets and is not backup. Files live under <strong>On My iPhone/iPad → Ableton Note</strong>. Help shows the version (Manual §2.5). Gates A–J are syllabus checkpoints."},{"type":"prose","html":"The index is a table you keep in Notes or on paper. Columns that stay sourced:"},{"type":"list","items":["Set name (you named it in Set Options)","Note version from Help at last save","Gate letter if it was a gate Set","Location: Local / Cloud / parked <code>.ablbundle</code>"],"ordered":false},{"type":"prose","html":"RN 1.5.2 / 1.0.14: rapid open/close and some library bugs could overwrite Sets historically. Unique names and this index are the defense. {type:'gap'} There is no official Note “index export.”"}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open the library. List every Local and Cloud Set you made for this course.","For each, open Help if needed and write the version.","Tag gate Sets (A–J) and lab Sets (L12).","Add parked bundles from Files.","Recite: eight Cloud slots; the index is your catalog, not Cloud."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why include version? <strong>Answer:</strong> 2.x audio vs 1.x sampler rules depend on it (RN / FAQ).","Why not put every Set in Cloud? <strong>Answer:</strong> Eight-slot transfer quota (FAQ).","Does Note generate this table? <strong>Answer:</strong> No. You write it."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (8 Sets; file path)","Ableton Note Manual §2.5, §3","Note Release Notes (library overwrite fixes)","Course syllabus gates"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Keep the table. 13.5.2 will pick three Cloud heroes from it."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-5-1</code></em>"}]}],"minutes":8},{"id":"note-l13-5-2","title":"13.5.2 — Pick 3 hero Sets for long-term Cloud slots","blocks":[{"type":"step","title":"13.5.2 — Pick 3 hero Sets for long-term Cloud slots","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.5 — Capstone portfolio index</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Choose three Sets to keep in Cloud long-term and leave the other five slots for active work."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Cloud = eight Sets, same account, transfer to Live / Note / Move / Push (FAQ; Manual §2.1 / §10.1). Move Cloud article: working the same Set on two devices at once is <strong>not</strong> supported. Sets &gt; 50 MB may fail to upload reliably on the Move path — keep heroes lean (crop, 100 MB sample cap)."},{"type":"prose","html":"Beatmaking: keep what stays memorable. Gate J capstone is usually hero 1. A lab that still teaches you something is hero 2. A 2.x audio experiment (if you have 2.0.1) is a good hero 3 because the version matters."},{"type":"prose","html":"The other five Cloud slots are a working buffer, not a museum."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["From the 13.5.1 index, star three Sets.","Upload those three if they are not in Cloud. Confirm they appear on Live’s Cloud label (11.2.5+).","Remove non-heroes from Cloud <strong>after</strong> they are local or parked (13.5.3).","Do not edit a Cloud hero on Move and Note at the same time (Move Cloud KB).","Recite: 3 heroes + 5 working slots = 8."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many Cloud Sets total? <strong>Answer:</strong> Eight.","Why not eight heroes? <strong>Answer:</strong> You still need slots for new sketches (FAQ: Cloud is transfer, not a vault).","Simultaneous edit on two devices? <strong>Answer:</strong> Not supported (Using Move with Ableton Cloud)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (8 Sets)","Using Move with Ableton Cloud (https://help.ableton.com/hc/en-us/articles/15599285481628)","Beatmaking with Ableton Note (memorable)","Note Release Notes 1.0.6 (100 MB)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write the three hero names on the index. Those names stay until you consciously replace one."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-5-2</code></em>"}]}],"minutes":8},{"id":"note-l13-5-3","title":"13.5.3 — Archive the rest via Share / Files","blocks":[{"type":"step","title":"13.5.3 — Archive the rest via Share / Files","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.5 — Capstone portfolio index</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Park every non-hero Set as an <code>.ablbundle</code> in Files (or AirDrop) before you delete or drop Cloud."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Sharing Note Sets KB: Set Options → <strong>Share To…</strong> → AirDrop / Files / other apps. The file is <strong><code>.ablbundle</code></strong> and opens in Note or Live 11.2.5+."},{"type":"prose","html":"FAQ: you can also Share To to move Sets without Cloud. Local Projects remain under Ableton Note in Files. Before deleting the <strong>app</strong>, back up the whole Ableton Note folder."},{"type":"prose","html":"Troubleshooting Note Files: duplicate Share To into the same Mac folder can break the extension (number after <code>.ablbundle</code> or missing extension). Rename to restore <code>.ablbundle</code> or share to a new folder."},{"type":"prose","html":"Archive ≠ Cloud. Cloud is eight live transfers."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["For each non-hero Set: <strong>Share To…</strong> → <strong>Files</strong> (or AirDrop to the computer).","Confirm the filename ends in <code>.ablbundle</code>.","Open one parked file in Note to prove it works, then close it.","Remove extras from Cloud. Keep heroes (13.5.2).","Recite: park first, then delete or drop Cloud."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What file type is a shared Set? <strong>Answer:</strong> <code>.ablbundle</code>.","What Mac naming bug should you watch for? <strong>Answer:</strong> A copy number after the extension, or a missing extension (Troubleshooting Note Files KB).","Does disabling Cloud on iOS wipe Live’s Cloud copies? <strong>Answer:</strong> Not by itself — account-level opt-out is different (that KB)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Sharing Note Sets (https://help.ableton.com/hc/en-us/articles/6121083513756)","Note FAQ (Share without Cloud; backup folder)","Troubleshooting Problems with Note Files"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Create a computer folder <code>NOTE-COURSE-ARCHIVE</code> and drop the bundles there. Update the index locations."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-5-3</code></em>"}]}],"minutes":8},{"id":"note-l13-5-4","title":"13.5.4 — Final reflection: what Note changed in your production habits","blocks":[{"type":"step","title":"13.5.4 — Final reflection: what Note changed in your production habits","blocks":[{"type":"prose","html":"<em>Level 13 · Module 13.5 — Capstone portfolio index</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Write a short sourced reflection: which official Note verbs you now do on the phone, and which jobs you still send to Live."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §1 verbs: sketch, capture, sample, send. Beatmaking: title, prompt, limitation, delay-before-judge, memorable ideas, 80/20."},{"type":"prose","html":"Honest comparison (syllabus 13.3 / product facts):"},{"type":"list","items":["Note strengths: Session speed, portability, constraint (8/8/16/8), Capture.","Live strengths: Arrangement, deep devices, mix, plugins.","One-way Cloud. No Android. No AUv3. Sampler warp vs 2.x audio-track warp."],"ordered":false},{"type":"prose","html":"This is not a test. It is the last Gate-adjacent document: if Gates A–J are ticked and ten sketches are archived (syllabus 13.4.6 graduation idea), you write what actually changed."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write four sentences, one per verb (sketch / capture / sample / send), each naming a control you now use.","Write one sentence you will <strong>not</strong> force in Note (Arrangement, AUv3, two-way Cloud).","Write one habit from Beatmaking you kept (delay, title, limitation).","Attach the index (13.5.1) and the three hero names.","Recite the four verbs from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What are Note’s four official jobs? <strong>Answer:</strong> Sketch, capture, sample, send (Manual §1).","What must stay in Live? <strong>Answer:</strong> Arrangement and any Live-only device/mix job.","Is this graded by software? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §1","Beatmaking with Ableton Note","Note FAQ / Compatibility (limits; one-way)","Course syllabus 13.3–13.5"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Store the reflection with the archive folder. The course pack stays on the desktop; the reflection is yours."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l13-5-4</code></em>"}]}],"minutes":8}],"exercises":[]}]};
